import java.io.*;
import java.util.*;

public class Check {
    static final int INF = (int)1e9;
    static final long MOD = 1000000007;

    static long compute(long n, long m) {
        long a = Math.min(n, m);
        long b = Math.max(n, m);
        long total = a * b;

        if (a <= 3 && b <= 3) {
            if (a == 1 || b == 1) return 0;
            if (a == 2 && b == 2) return 0;
            if (a == 2 && b == 3) return 4;
            if (a == 3 && b == 2) return 4;
            if (a == 3 && b == 3) return 8;
            return 0;
        }

        if (a == 1) {
            long modVal = b % 6;
            if (modVal == 4) modVal = 2;
            else if (modVal == 5) modVal = 1;
            return total - modVal;
        } else if (a == 2) {
            if (b == 3 || b == 7) b = 2;
            else b = 0;
            return total - b;
        } else {
            return total - (total % 2);
        }
    }

    public static void main(String[] args) throws IOException {
        boolean debugMode = args.length > 0 && args[0].equalsIgnoreCase("d");
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String[] input = reader.readLine().split(" ");
        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        long result = compute(n, m);
        writer.println(result);
        writer.close();
    }
}
